+    final r = await Process.run('git', args,
+        workingDirectory: dir,
+        environment: {
+          ...Platform.environment,
+          'GIT_AUTHOR_NAME': 't',
+          'GIT_AUTHOR_EMAIL': 't@t',
+          'GIT_COMMITTER_NAME': 't',
+          'GIT_COMMITTER_EMAIL': 't@t',
+        });
+    expect(r.exitCode, 0, reason: 'git ${args.join(' ')}: ${r.stderr}');
+  }
